CREATE TABLE `tbtransporte` (
  `idtbtransporte` int(11) NOT NULL auto_increment,
  `zona` varchar(25) default NULL,
  `base` varchar(25) default NULL,
  `tarifa_premium_carro_movil` decimal(19,0) default NULL,
  `tarifa_premium_codec` decimal(19,0) default NULL,
  `tarifa_premium_monitor` decimal(19,0) default NULL,
  `entrega_premium` varchar(15) default NULL,
  `tarifa_priority_carro_movil` decimal(19,0) default NULL,
  `tarifa_priority_codec` decimal(19,0) default NULL,
  `tarifa_priority_monitor` decimal(19,0) default NULL,
  `entrega_priority` varchar(15) default NULL,
  `tarifa_express_carro_movil` decimal(19,0) default NULL,
  `tarifa_express_codec` decimal(19,0) default NULL,
  `tarifa_express_monitor` decimal(19,0) default NULL,
  `entrega_express` varchar(15) default NULL,
  PRIMARY KEY  (`idtbtransporte`)
) ENGINE=MyISAM AUTO_INCREMENT=81 DEFAULT CHARSET=utf8;
